        if (next != null) {
            next.prev = prev;
        } else {
            // node was the last element
            last = prev;
        }

        // Help GC
        node.prev = null;
        node.next = null;
        size--;

        return true;
    } catch (Exception e) {
        // The node might not belong to this list or some other error occurred
